"use client";

import { useState, type ComponentProps, type ReactNode } from "react";
import {
  Box,
  Camera,
  Check,
  ChevronDown,
  Copy,
  Download,
  Footprints,
  Gauge,
  Grid2X2,
  LayoutGrid,
  ListTree,
  Moon,
  Pause,
  Play,
  Rotate3D,
  RotateCcw,
  ScanSearch,
  Sun,
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { ViewerControlButton as Button } from "./viewer-ui";
import type {
  ViewerMode,
  ViewerLighting,
  ViewerShading,
  ViewerViewCube,
} from "./model-viewer";
import "./model-viewer.css";

export function ModelViewerToolbar({
  className,
  onKeyDown,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      data-slot="model-viewer-toolbar"
      role="toolbar"
      aria-label="3D viewer controls"
      className={cn("viewer-toolbar", className)}
      {...props}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (
          event.defaultPrevented ||
          event.altKey ||
          event.ctrlKey ||
          event.metaKey
        )
          return;
        if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key))
          return;
        // Ignore events from portaled menus and editable controls.
        const target = event.target as HTMLElement;
        if (!event.currentTarget.contains(target) || !target.closest("button"))
          return;
        const buttons = [
          ...event.currentTarget.querySelectorAll<HTMLButtonElement>(
            "button:not(:disabled)",
          ),
        ];
        const current = buttons.indexOf(target.closest("button")!);
        if (current < 0 || buttons.length === 0) return;
        const next =
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? buttons.length - 1
              : (current +
                  (event.key === "ArrowRight" ? 1 : -1) +
                  buttons.length) %
                buttons.length;
        event.preventDefault();
        buttons[next].focus();
      }}
    />
  );
}

export function ModelViewerToolbarGroup({
  className,
  ...props
}: ComponentProps<"div">) {
  return (
    <div
      data-slot="model-viewer-toolbar-group"
      role="group"
      className={cn("viewer-toolbar-group", className)}
      {...props}
    />
  );
}

export type ModelViewerToolbarButtonProps = ComponentProps<typeof Button> & {
  label: string;
  active?: boolean;
  icon?: ReactNode;
};

export function ModelViewerToolbarButton({
  label,
  active,
  icon,
  children,
  ...props
}: ModelViewerToolbarButtonProps) {
  return (
    <Button
      data-slot="model-viewer-toolbar-button"
      data-state={active === undefined ? undefined : active ? "on" : "off"}
      size="icon-sm"
      variant={active ? "secondary" : "ghost"}
      aria-label={label}
      aria-pressed={active}
      tooltip={label}
      {...props}
    >
      {children ?? icon}
    </Button>
  );
}

export type ModelViewerControlsProps = ComponentProps<"div"> & {
  mode: ViewerMode;
  onModeChange: (mode: ViewerMode) => void;
  shading: ViewerShading;
  onShadingChange: (shading: ViewerShading) => void;
  lighting: ViewerLighting;
  onLightingChange: (lighting: ViewerLighting) => void;
  grid: boolean;
  onGridChange: (visible: boolean) => void;
  projection: "perspective" | "orthographic";
  onProjectionChange: (projection: "perspective" | "orthographic") => void;
  viewCube: ViewerViewCube | false;
  onViewCubeChange: (viewCube: ViewerViewCube | false) => void;
  inspectorOpen: boolean;
  onInspectorChange: (open: boolean) => void;
  onReset: () => void;
  captureDisabled?: boolean;
  onCapture: (action: "copy" | "download") => void;
};

/** The default controls, also usable outside ModelViewer with controlled state. */
export function ModelViewerControls({
  mode,
  onModeChange,
  shading,
  onShadingChange,
  lighting,
  onLightingChange,
  grid,
  onGridChange,
  projection,
  onProjectionChange,
  viewCube,
  onViewCubeChange,
  inspectorOpen,
  onInspectorChange,
  onReset,
  captureDisabled,
  onCapture,
  ...props
}: ModelViewerControlsProps) {
  const [captureMenuOpen, setCaptureMenuOpen] = useState(false);
  return (
    <ModelViewerToolbar {...props}>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            type="button"
            variant="outline"
            className="viewer-shading-trigger text-[10px] font-semibold"
            aria-label={`Shading: ${shading}`}
          >
            {shading}
            <ChevronDown />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          sideOffset={6}
          className="viewer-menu"
        >
          {(["realistic", "solid", "normals", "wireframe"] as const).map(
            (option) => (
              <DropdownMenuItem
                key={option}
                onSelect={() => onShadingChange(option)}
              >
                <Check
                  className={option === shading ? "is-visible" : "is-hidden"}
                />
                <span>{option}</span>
              </DropdownMenuItem>
            ),
          )}
        </DropdownMenuContent>
      </DropdownMenu>
      <ModelViewerToolbarGroup aria-label="Interaction mode">
        <ModelViewerToolbarButton
          icon={<Rotate3D />}
          label="Orbit camera"
          active={mode === "orbit"}
          onClick={() => onModeChange("orbit")}
        />
        <ModelViewerToolbarButton
          icon={<LayoutGrid />}
          label="Four-view split"
          active={mode === "split"}
          onClick={() => onModeChange("split")}
        />
        <ModelViewerToolbarButton
          icon={<Footprints />}
          label="Fly camera"
          active={mode === "firstPerson"}
          onClick={() => onModeChange("firstPerson")}
        />
      </ModelViewerToolbarGroup>
      <ModelViewerToolbarGroup aria-label="Scene options">
        <ModelViewerToolbarButton
          icon={lighting === "day" ? <Sun /> : <Moon />}
          label={lighting === "day" ? "Switch to night" : "Switch to day"}
          active={lighting === "night"}
          onClick={() => onLightingChange(lighting === "day" ? "night" : "day")}
        />
        <ModelViewerToolbarButton
          icon={<Grid2X2 />}
          label="Show grid"
          active={grid}
          onClick={() => onGridChange(!grid)}
        />
        <ModelViewerToolbarButton
          icon={<ScanSearch />}
          label="Orthographic view"
          active={projection === "orthographic"}
          onClick={() =>
            onProjectionChange(
              projection === "orthographic" ? "perspective" : "orthographic",
            )
          }
        />
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              size="icon-sm"
              variant="ghost"
              aria-label="View cube options"
            >
              <Box />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent className="viewer-menu">
            {([false, "drei", "asset-studio"] as const).map((value) => (
              <DropdownMenuItem
                key={String(value)}
                onSelect={() => onViewCubeChange(value)}
              >
                <Check
                  className={viewCube === value ? "is-visible" : "is-hidden"}
                />
                {value === false
                  ? "Off"
                  : value === "drei"
                    ? "Drei cube"
                    : "Asset Studio"}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        <ModelViewerToolbarButton
          icon={<ListTree />}
          label="Inspect model"
          active={inspectorOpen}
          onClick={() => onInspectorChange(!inspectorOpen)}
        />
        <ModelViewerToolbarButton
          icon={<RotateCcw />}
          label="Reset view"
          onClick={onReset}
        />
        <DropdownMenu open={captureMenuOpen} onOpenChange={setCaptureMenuOpen}>
          <DropdownMenuTrigger asChild>
            <Button
              type="button"
              size="icon-sm"
              variant={captureMenuOpen ? "secondary" : "ghost"}
              aria-label="Screenshot options"
              title="Screenshot options"
              disabled={captureDisabled}
            >
              <Camera />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="end"
            sideOffset={8}
            className="viewer-capture-menu"
          >
            <div className="viewer-capture-title">
              Capture view <span>PNG</span>
            </div>
            <DropdownMenuItem onSelect={() => void onCapture("copy")}>
              <Copy /> Copy to clipboard
            </DropdownMenuItem>
            <DropdownMenuItem onSelect={() => void onCapture("download")}>
              <Download /> Download image
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </ModelViewerToolbarGroup>
    </ModelViewerToolbar>
  );
}

const animationSpeeds = [0.5, 1, 1.5, 2];

export type ModelViewerAnimationControlsProps = ComponentProps<"div"> & {
  clips: string[];
  animation: string | null;
  onAnimationChange: (clip: string) => void;
  playing: boolean;
  onPlayingChange: (playing: boolean) => void;
  speed: number;
  onSpeedChange: (speed: number) => void;
  onRestart: () => void;
};

export function ModelViewerAnimationControls({
  clips,
  animation,
  onAnimationChange,
  playing,
  onPlayingChange,
  speed,
  onSpeedChange,
  onRestart,
  className,
  ...props
}: ModelViewerAnimationControlsProps) {
  return (
    <ModelViewerToolbar
      data-slot="model-viewer-animation-controls"
      aria-label="Animation controls"
      className={cn("viewer-animation-controls", className)}
      {...props}
    >
      <ModelViewerToolbarButton
        icon={playing ? <Pause /> : <Play />}
        label={playing ? "Pause animation" : "Play animation"}
        active={playing}
        onClick={() => onPlayingChange(!playing)}
      />
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            type="button"
            size="sm"
            variant="ghost"
            className="viewer-animation-name"
          >
            {animation ?? "No animation"}
            <ChevronDown />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="start"
          sideOffset={6}
          className="viewer-animation-menu"
        >
          {clips.map((name) => (
            <DropdownMenuItem
              key={name}
              onSelect={() => onAnimationChange(name)}
            >
              <Check
                className={name === animation ? "is-visible" : "is-hidden"}
              />
              {name}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
      <ModelViewerToolbarButton
        icon={<RotateCcw />}
        label="Restart animation"
        onClick={onRestart}
      />
      <Button
        type="button"
        size="icon-sm"
        variant="ghost"
        aria-label={`Animation speed ${speed}×`}
        title={`Animation speed ${speed}×`}
        onClick={() =>
          onSpeedChange(
            animationSpeeds[
              (animationSpeeds.indexOf(speed) + 1) % animationSpeeds.length
            ] ?? 1,
          )
        }
      >
        <Gauge />
        <span className="viewer-speed-label">{speed}×</span>
      </Button>
    </ModelViewerToolbar>
  );
}

"use client";

import {
  Box,
  ChevronDown,
  ChevronRight,
  Crosshair,
  Image,
  Layers,
  Search,
  Triangle,
  X,
} from "lucide-react";
import { useId, useMemo, useState, type ComponentProps } from "react";
import { cn } from "@/lib/utils";
import type { ModelInspection } from "./model-inspection";
import {
  ViewerControlButton as Button,
  ViewerUiProvider,
  type ViewerUiComponents,
} from "./viewer-ui";
import "./model-viewer.css";

export type ModelInspectorProps = ComponentProps<"aside"> & {
  inspection: ModelInspection;
  selectedMesh?: string | null;
  onSelectMesh: (id: string | null) => void;
  onClose?: () => void;
  className?: string;
  components?: Partial<ViewerUiComponents>;
};

export function ModelInspector({
  inspection,
  selectedMesh,
  onSelectMesh,
  onClose,
  className,
  components,
  ...props
}: ModelInspectorProps) {
  const [query, setQuery] = useState("");
  const [collapsed, setCollapsed] = useState<Set<string>>(() => new Set());
  const heading = useId();
  const selected = inspection.nodes.find((node) => node.id === selectedMesh);
  const parentIds = useMemo(
    () =>
      new Set(
        inspection.nodes.map((node) =>
          node.id.slice(0, node.id.lastIndexOf("/")),
        ),
      ),
    [inspection.nodes],
  );
  const matching = inspection.nodes.filter((node) =>
    node.name.toLowerCase().includes(query.toLowerCase()),
  );
  const visible = inspection.nodes.filter((node) =>
    query
      ? matching.some(
          (match) => match.id === node.id || match.id.startsWith(`${node.id}/`),
        )
      : ![...collapsed].some((id) => node.id.startsWith(`${id}/`)),
  );
  function toggle(id: string) {
    setCollapsed((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  }

  return (
    <ViewerUiProvider components={components}>
      <aside
        data-slot="model-inspector"
        className={cn("viewer-inspector", className)}
        aria-labelledby={heading}
        {...props}
      >
        <header className="inspector-header">
          <span className="inspector-emblem">
            <Box size={18} />
          </span>
          <div>
            <span className="inspector-eyebrow">Scene overview</span>
            <h3 id={heading}>Model inspector</h3>
          </div>
          {onClose && (
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Close inspector"
              onClick={onClose}
            >
              <X size={16} />
            </Button>
          )}
        </header>
        <div className="inspector-metrics">
          {[
            { label: "Triangles", value: inspection.triangles, Icon: Triangle },
            { label: "Materials", value: inspection.materials, Icon: Layers },
            { label: "Textures", value: inspection.textures, Icon: Image },
          ].map(({ label, value, Icon }) => (
            <div key={label}>
              <Icon size={14} />
              <strong>{value.toLocaleString()}</strong>
              <span>{label}</span>
            </div>
          ))}
        </div>
        <section className="inspector-dimensions" aria-label="Dimensions">
          <div className="inspector-section-label">
            Dimensions <span>model units</span>
          </div>
          <div className="inspector-axis-values">
            {inspection.dimensions.map((value, index) => (
              <div key={index}>
                <span data-axis={index}>{["X", "Y", "Z"][index]}</span>
                <strong>{Number(value.toPrecision(4))}</strong>
              </div>
            ))}
          </div>
        </section>
        <div className="inspector-hierarchy-heading">
          <span className="inspector-section-label">Hierarchy</span>
          <span>
            {inspection.nodes.filter((node) => node.mesh).length} meshes
          </span>
        </div>
        <label className="inspector-search">
          <Search size={14} />
          <input
            aria-label="Search hierarchy"
            placeholder="Find an object…"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
          {query && (
            <Button
              size="icon-sm"
              variant="ghost"
              aria-label="Clear search"
              onClick={() => setQuery("")}
            >
              <X size={12} />
            </Button>
          )}
        </label>
        <ul className="inspector-tree" aria-label="Scene hierarchy">
          {visible.map((node) => {
            const hasChildren = parentIds.has(node.id);
            return (
              <li
                data-slot="model-inspector-node"
                data-state={selectedMesh === node.id ? "selected" : undefined}
                key={node.id}
                style={{ paddingLeft: Math.min(node.depth, 8) * 12 }}
                className={cn(selectedMesh === node.id && "is-selected")}
              >
                {hasChildren ? (
                  <Button
                    size="icon-sm"
                    variant="ghost"
                    className="inspector-expand h-[26px] w-[22px] p-0"
                    aria-label={`${collapsed.has(node.id) ? "Expand" : "Collapse"} ${node.name}`}
                    aria-expanded={!collapsed.has(node.id)}
                    onClick={() => toggle(node.id)}
                  >
                    {collapsed.has(node.id) ? (
                      <ChevronRight size={12} />
                    ) : (
                      <ChevronDown size={12} />
                    )}
                  </Button>
                ) : (
                  <span className="inspector-spacer" />
                )}
                <Button
                  variant="ghost"
                  size="sm"
                  className="inspector-node h-[30px] min-w-0 flex-1 justify-start gap-[7px] p-1 text-[11px]"
                  disabled={!node.mesh}
                  aria-pressed={
                    node.mesh ? selectedMesh === node.id : undefined
                  }
                  onClick={() => onSelectMesh(node.id)}
                >
                  {node.mesh ? <Box size={13} /> : <Layers size={13} />}
                  <span>{node.name}</span>
                  <small>{node.mesh ? "Mesh" : node.type}</small>
                </Button>
              </li>
            );
          })}
        </ul>
        {visible.length === 0 && (
          <div className="inspector-empty">No objects match “{query}”.</div>
        )}
        <footer className="inspector-selection">
          <Crosshair size={15} />
          <div>
            <span>{selected ? "Selected object" : "Nothing selected"}</span>
            <strong>{selected?.name ?? "Choose a mesh to inspect"}</strong>
          </div>
          {selected && (
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Clear selection"
              onClick={() => onSelectMesh(null)}
            >
              <X size={14} />
            </Button>
          )}
        </footer>
      </aside>
    </ViewerUiProvider>
  );
}

"use client";

import {
  createContext,
  useContext,
  useMemo,
  type ComponentProps,
  type ComponentType,
  type ReactElement,
  type ReactNode,
} from "react";
import { Button as ShadcnButton } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

export type ViewerTooltipProps = { children: ReactElement; content: ReactNode };
export type ViewerUiComponents = {
  /** Forward the ref, event handlers, aria attributes, and className to the underlying button. */
  Button: ComponentType<ComponentProps<typeof ShadcnButton>>;
  /** Render children as the trigger, preserving its ref and event handlers. */
  Tooltip: ComponentType<ViewerTooltipProps>;
};

function DefaultTooltip({ children, content }: ViewerTooltipProps) {
  const hasProvider = useContext(ViewerUiContext) !== null;
  const tooltip = (
    <Tooltip>
      <TooltipTrigger asChild>{children}</TooltipTrigger>
      <TooltipContent>{content}</TooltipContent>
    </Tooltip>
  );
  return hasProvider ? (
    tooltip
  ) : (
    <TooltipProvider delayDuration={350}>{tooltip}</TooltipProvider>
  );
}

const defaultComponents: ViewerUiComponents = {
  Button: ShadcnButton,
  Tooltip: DefaultTooltip,
};
const ViewerUiContext = createContext<ViewerUiComponents | null>(null);

export function ViewerUiProvider({
  components,
  children,
}: {
  components?: Partial<ViewerUiComponents>;
  children: ReactNode;
}) {
  const inherited = useContext(ViewerUiContext) ?? defaultComponents;
  const value = useMemo(
    () => ({ ...inherited, ...components }),
    [inherited, components],
  );
  return (
    <ViewerUiContext.Provider value={value}>
      <TooltipProvider delayDuration={350}>{children}</TooltipProvider>
    </ViewerUiContext.Provider>
  );
}

export type ViewerControlButtonProps = ComponentProps<typeof ShadcnButton> & {
  /** Override the accessible-label tooltip, or use false to disable it. */
  tooltip?: ReactNode | false;
};

export function ViewerControlButton({
  title,
  tooltip,
  type = "button",
  ...props
}: ViewerControlButtonProps) {
  const { Button, Tooltip: TooltipImpl } =
    useContext(ViewerUiContext) ?? defaultComponents;
  const label =
    tooltip === undefined ? (title ?? props["aria-label"]) : tooltip;
  const button = <Button type={type} {...props} />;
  return label ? <TooltipImpl content={label}>{button}</TooltipImpl> : button;
}

"use client";

import { GizmoHelper, GizmoViewcube } from "@react-three/drei";
import type { ComponentProps } from "react";
import { ViewHelper } from "./view-helper";

export type ViewCubePosition = NonNullable<ComponentProps<typeof GizmoHelper>["alignment"]>;
export type ViewCubeProps = {
  variant?: "drei" | "asset-studio";
  position?: ViewCubePosition;
  margin?: [number, number];
  renderPriority?: number;
};

/** Compose inside an R3F Canvas with default camera controls. */
export function ViewCube({ variant = "asset-studio", position = "top-right", margin = [64, 64], renderPriority = 1 }: ViewCubeProps) {
  return (
    <GizmoHelper alignment={position} margin={margin} renderPriority={renderPriority}>
      {variant === "drei" ? <GizmoViewcube /> : <ViewHelper />}
    </GizmoHelper>
  );
}

import { AnimationMixer, Box3, Sphere, Vector3, type AnimationClip, type Object3D, type Mesh, type Material, type Texture } from "three";
import { clone } from "three/addons/utils/SkeletonUtils.js";

const sampled = new WeakSet<Object3D>();

/** Cache a conservative sampled envelope without changing the loader's shared pose. */
export function prepareAnimationBounds(root: Object3D, clips: AnimationClip[]) {
  if (sampled.has(root) || clips.length === 0) return;
  sampled.add(root);
  root.updateMatrixWorld(true);
  const copy = clone(root);
  copy.updateMatrixWorld(true);
  const mixer = new AnimationMixer(copy);
  const box = new Box3().setFromObject(copy, true);
  for (const clip of clips) {
    const action = mixer.clipAction(clip).play();
    for (let sample = 0; sample <= 16; sample++) {
      mixer.setTime(clip.duration * sample / 16);
      copy.updateMatrixWorld(true);
      box.union(new Box3().setFromObject(copy, true));
    }
    action.stop();
  }
  mixer.stopAllAction();
  mixer.uncacheRoot(copy);
  copy.updateMatrixWorld(true);
  box.applyMatrix4(copy.matrixWorld.clone().invert());
  root.userData.viewerAnimationBounds = [box.min.toArray(), box.max.toArray()];
}

export type ModelInspection = {
  dimensions: [number, number, number];
  triangles: number;
  materials: number;
  textures: number;
  nodes: { id: string; name: string; type: string; depth: number; mesh: boolean }[];
};

export function inspectModel(root: Object3D): ModelInspection {
  root.updateWorldMatrix(true, true);
  const materials = new Set<Material>();
  const textures = new Set<Texture>();
  let triangles = 0;
  const nodes: ModelInspection["nodes"] = [];
  function visit(object: Object3D, path: string, depth: number) {
    object.userData.viewerNodeId = path;
    const mesh = object as Mesh;
    nodes.push({ id: path, name: object.name || object.type, type: object.type, depth, mesh: Boolean(mesh.isMesh) });
    if (mesh.isMesh) {
      triangles += ((mesh.geometry.index?.count ?? mesh.geometry.attributes.position?.count ?? 0) / 3) * ((mesh as Mesh & { count?: number }).count ?? 1);
      for (const material of Array.isArray(mesh.material) ? mesh.material : [mesh.material]) {
        materials.add(material);
        for (const value of Object.values(material)) if (value?.isTexture) textures.add(value);
      }
    }
    object.children.forEach((child, index) => visit(child, `${path}/${index}`, depth + 1));
  }
  visit(root, "0", 0);
  return { dimensions: new Box3().setFromObject(root, true).getSize(new Vector3()).toArray(), triangles: Math.round(triangles), materials: materials.size, textures: textures.size, nodes };
}

export function frameBounds(object: Object3D, aspect: number, fov = 42) {
  object.updateWorldMatrix(true, true);
  const box = new Box3().setFromObject(object, true);
  object.traverse(node => {
    const bounds = node.userData.viewerAnimationBounds as [number[], number[]] | undefined;
    if (bounds) box.union(new Box3(new Vector3().fromArray(bounds[0]), new Vector3().fromArray(bounds[1])).applyMatrix4(node.matrixWorld));
  });
  const sphere = box.getBoundingSphere(new Sphere());
  const radius = Number.isFinite(sphere.radius) && sphere.radius > 0 ? sphere.radius : 0.001;
  const center = box.isEmpty() ? new Vector3() : sphere.center;
  const halfFov = fov * Math.PI / 360;
  const limitingAngle = Math.min(halfFov, Math.atan(Math.tan(halfFov) * Math.max(aspect, 0.001)));
  const distance = radius / Math.sin(limitingAngle) * 1.15;
  return { center, radius, distance, near: Math.max(radius / 1000, 1e-8), far: distance + radius * 100 };
}

"use client";

